<template>
  <section class="sku-list-page">
    <header class="page-head"><div><h1>SKU管理</h1><p>SKU与图片来自已导入的新系统主数据；列表不会读取旧库或自动同步。</p></div><div class="head-actions"><el-button size="small" icon="el-icon-refresh" @click="fetch">刷新</el-button><el-button size="small" type="success" icon="el-icon-plus" @click="$router.push('/master/skus/new')">新增 SKU</el-button></div></header>
    <div class="filters"><el-input v-model="query.keyword" size="small" clearable placeholder="SKU编码 / 名称 / 规格" @keyup.enter.native="search" /><el-select v-model="query.order_line_type" size="small" clearable placeholder="订单行类型"><el-option label="实物" value="physical" /><el-option label="服务" value="service" /><el-option label="无需发货" value="no_delivery" /></el-select><el-select v-model="query.status" size="small" clearable placeholder="状态"><el-option label="草稿" value="draft" /><el-option label="启用" value="enabled" /><el-option label="停用" value="disabled" /></el-select><el-checkbox v-model="query.missing_default_item">缺少默认Item</el-checkbox><el-button size="small" type="primary" @click="search">查询</el-button><el-button size="small" @click="reset">重置</el-button></div>
    <el-alert title="实物SKU启用前必须有唯一有效的默认Item；服务和无需发货SKU不要求绑定Item。" type="info" :closable="false" show-icon />
    <div class="table-card"><el-table v-loading="loading" :data="rows" size="small" border><el-table-column label="图片" width="74" align="center"><template slot-scope="{ row }"><el-image v-if="imageUrl(row)" class="sku-thumb" :src="imageUrl(row)" fit="cover" :preview-src-list="[imageUrl(row)]"><div slot="error" class="image-fallback">暂无</div></el-image><div v-else class="image-fallback">暂无</div></template></el-table-column><el-table-column prop="sku_code" label="SKU编码" min-width="142" show-overflow-tooltip /><el-table-column prop="sku_name" label="SKU名称" min-width="180" show-overflow-tooltip /><el-table-column label="Product" min-width="190" show-overflow-tooltip><template slot-scope="{ row }">{{ productText(row) }}</template></el-table-column><el-table-column label="销售单位 / 默认价" min-width="138"><template slot-scope="{ row }"><span v-if="row.sales_unit_id && row.sale_price !== null && row.sale_price !== ''">{{ unitName(row) }} / ¥{{ Number(row.sale_price).toFixed(2) }}</span><el-tag v-else type="warning" size="mini">待补全</el-tag></template></el-table-column><el-table-column label="订单行类型" width="104"><template slot-scope="{ row }">{{ typeText(row.line_type || row.order_line_type) }}</template></el-table-column><el-table-column label="默认Item" min-width="150"><template slot-scope="{ row }"><el-tag v-if="hasDefault(row)" type="success" size="mini">{{ defaultItem(row).item.item_code }}</el-tag><el-tag v-else-if="(row.line_type || row.order_line_type) === 'physical' && row.status === 'enabled'" type="danger" size="mini">缺少默认Item</el-tag><span v-else>—</span></template></el-table-column><el-table-column label="状态" width="82"><template slot-scope="{ row }"><el-tag size="mini" :type="row.status === 'enabled' ? 'success' : row.status === 'draft' ? 'warning' : 'info'">{{ statusText(row.status) }}</el-tag></template></el-table-column><el-table-column label="操作" fixed="right" width="222"><template slot-scope="{ row }"><el-button type="text" size="mini" @click="$router.push('/master/skus/' + row.id)">详情</el-button><el-button type="text" size="mini" @click="$router.push('/master/skus/' + row.id + '/edit')">编辑</el-button><el-button type="text" size="mini" :class="row.status==='enabled'?'danger-link':'success-link'" @click="toggleStatus(row)">{{ row.status==='enabled'?'停用':'启用' }}</el-button><el-button v-if="row.status!=='enabled'" type="text" size="mini" class="danger-link" @click="deleteSku(row)">删除</el-button></template></el-table-column></el-table><div class="pager"><span>共 {{ total }} 条</span><el-pagination small layout="prev, pager, next, sizes" :current-page="query.page" :page-size="query.per_page" :page-sizes="[10,20,50]" :total="total" @current-change="changePage" @size-change="changeSize" /></div></div>
  </section>
</template>
<script>
import { deleteEntity, disableEntity, enableEntity, listEntity } from '../../../api/erp/master'
import { legacyMediaUrl } from '../../../utils/legacyMedia'
export default { name:'SkuList', data(){return { loading:false,rows:[],total:0,query:{keyword:'',order_line_type:'',status:'',missing_default_item:false,page:1,per_page:20} }},created(){this.fetch()},methods:{async fetch(){this.loading=true;try{const response=await listEntity('skus',this.query);this.rows=response.data.data||[];this.total=response.data.total||0}catch(error){this.$message.error(error.userMessage||'SKU加载失败')}finally{this.loading=false}},search(){this.query.page=1;this.fetch()},reset(){this.query={keyword:'',order_line_type:'',status:'',missing_default_item:false,page:1,per_page:20};this.fetch()},changePage(page){this.query.page=page;this.fetch()},changeSize(size){this.query.per_page=size;this.query.page=1;this.fetch()},async toggleStatus(row){const enabling=row.status!=='enabled';try{await this.$confirm(enabling?'确认启用该 SKU？':'确认停用该 SKU？',enabling?'启用SKU':'停用SKU',{type:'warning'});await(enabling?enableEntity:disableEntity)('skus',row.id);this.$message.success(enabling?'SKU已启用':'SKU已停用');await this.fetch()}catch(e){if(e!=='cancel'&&e!=='close')this.$message.error(e.userMessage||'SKU状态更新失败')}},async deleteSku(row){try{await this.$confirm(`确认删除 SKU ${row.sku_code}？仅从未被订单、BOM、定制或默认 Item 关系引用的停用/草稿 SKU 可以删除。`,'删除SKU',{type:'warning',confirmButtonText:'确认删除'});await deleteEntity('skus',row.id);this.$message.success('SKU已删除');await this.fetch()}catch(e){if(e!=='cancel'&&e!=='close')this.$message.error(e.userMessage||'SKU删除失败')}},imageUrl(row){return legacyMediaUrl(row.image||(row.product&&row.product.image))},defaultItem:row=>(row.item_relations||[]).find(item=>item.status==='active'&&item.is_primary&&item.item&&item.item.status==='enabled'),hasDefault(row){return !!this.defaultItem(row)},productText(row){return row.product?`${row.product.product_code}｜${row.product.product_name}`:'—'},unitName(row){return (row.sales_unit&&row.sales_unit.unit_name)||row.sales_unit_snapshot||'—'},needsCompletion(row){return row.status==='draft'&&!(row.sales_unit_id&&row.sale_price!==null&&row.sale_price!==''&&((row.line_type||row.order_line_type)!=='physical'||this.hasDefault(row)))},typeText:value=>({physical:'实物',service:'服务',no_delivery:'无需发货'})[value]||value,statusText:value=>({draft:'草稿',enabled:'启用',disabled:'停用'})[value]||value}}
</script>
<style scoped>.sku-list-page{min-height:calc(100vh - 52px);padding:18px;background:#f6f8f8}.page-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:14px}.page-head h1{margin:0;color:#1f2d3d;font-size:18px}.page-head p{margin:6px 0 0;color:#75808a;font-size:12px}.head-actions{display:flex;gap:8px}.filters{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:12px;margin-bottom:10px;background:#fff;border:1px solid #e5eaec}.filters .el-input{width:240px}.filters .el-select{width:140px}.sku-list-page>.el-alert{margin-bottom:10px}.table-card{overflow:hidden;background:#fff;border:1px solid #e5eaec}.sku-thumb,.image-fallback{width:42px;height:42px;border-radius:4px}.image-fallback{display:inline-flex;align-items:center;justify-content:center;color:#a5afb9;font-size:11px;background:#f3f5f7}.pager{display:flex;justify-content:flex-end;align-items:center;gap:18px;height:52px;padding:0 14px;color:#68737d;font-size:12px}.danger-link{color:#e54848!important}.success-link{color:#07883f!important}</style>
